local cell = require "claviron.orbit.cell"
assert(cell == claviron.cell)
local n = claviron.cell(math.maxinteger - 1)
assert(n:kind() == "int" and claviron.cell(0.5):kind() == "float")
assert(not pcall(claviron.cell), "a cell needs its first value")
assert(n:add(1) == math.maxinteger)
assert(n > 3 and 3 < n and n >= n and n:get() == math.maxinteger)
assert(n == cell.open(n:id()))
local took, taken, after = cell.int(0):add_until(5, 3)
assert(took and taken == 3 and after == 3)
local log = cell.string("a")
assert(log:append("b") == "ab" and tostring(log) == "ab")
assert(not pcall(n.set, n, "text"))
print(n:id())
